// Buckets conversations by their creation date (not last-updated) so the sidebar reads like a real
// history a person can revisit by "when" — Today / Yesterday / Previous 7 days / Older — rather than
// a flat list that reorders itself every time an old chat happens to get a new reply.
function groupConversationsByDate<T extends { createdAt: Date | string }>(items: T[]): { label: string; items: T[] }[] {
  const startOfDay = (d: Date) => { const x = new Date(d); x.setHours(0, 0, 0, 0); return x; };
  const today = startOfDay(new Date());
  const yesterday = new Date(today); yesterday.setDate(yesterday.getDate() - 1);
  const weekAgo = new Date(today); weekAgo.setDate(weekAgo.getDate() - 7);
  const buckets: { label: string; items: T[] }[] = [{ label: "Today", items: [] }, { label: "Yesterday", items: [] }, { label: "Previous 7 days", items: [] }, { label: "Older", items: [] }];
  for (const item of items) {
    const created = startOfDay(new Date(item.createdAt));
    if (created.getTime() === today.getTime()) buckets[0].items.push(item);
    else if (created.getTime() === yesterday.getTime()) buckets[1].items.push(item);
    else if (created.getTime() > weekAgo.getTime()) buckets[2].items.push(item);
    else buckets[3].items.push(item);
  }
  return buckets.filter(b => b.items.length > 0);
}

// Starting an application from an opportunity is the one case where the Organisation field can be
// safely pre-filled — every value here comes straight off the opportunity itself (real, already
// verified enough to be shown), never guessed. The deadline text is folded into notes instead of a
// date input, since curated/live deadlines only ever arrive as a formatted display string, not a
// raw date PathFinder can trust into an ISO value.
function buildApplicationPrefillFromOpportunity(o: { title: string; org: string; category: string; deadline?: string; sourceUrl?: string }) {
  const noteParts: string[] = [];
  if (o.deadline && !["Rolling", "Verify source", "No deadline"].includes(o.deadline)) noteParts.push(`Deadline: ${o.deadline}`);
  if (o.sourceUrl) noteParts.push(`Source: ${o.sourceUrl}`);
  return { title: o.title, organisation: o.org, type: o.category, notes: noteParts.length ? noteParts.join(" · ") : undefined, dateApplied: new Date().toISOString().slice(0, 10) };
}

