function AuthModal({ mode, onClose, onSuccess, onSwitchMode }: { mode: "signin" | "signup"; onClose: () => void; onSuccess: () => void; onSwitchMode: (m: "signin" | "signup") => void }) {
  const [form, setForm] = useState({ name: "", email: "", password: "" });
  const [error, setError] = useState<string | null>(null);
  const utils = trpc.useUtils();
  const registerMutation = trpc.auth.register.useMutation();
  const loginMutation = trpc.auth.login.useMutation();
  const pending = registerMutation.isPending || loginMutation.isPending;
  const liveIssues = mode === "signup" && form.password ? passwordIssues(form.password) : [];
  async function submit() {
    setError(null);
    if (mode === "signup") {
      if (!form.name.trim()) { setError("Enter your name."); return; }
      if (!isValidEmail(form.email)) { setError("Enter a valid email address."); return; }
      const issues = passwordIssues(form.password);
      if (issues.length) { setError(issues.join(" ")); return; }
    }
    try {
      if (mode === "signup") await registerMutation.mutateAsync({ name: form.name, email: form.email, password: form.password });
      else await loginMutation.mutateAsync({ email: form.email, password: form.password });
      await utils.auth.me.invalidate();
      onSuccess();
    } catch (err: any) {
      setError(err?.message || "Something went wrong. Please try again.");
    }
  }
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#183b56]/35 p-4 backdrop-blur-sm"><div className="max-h-[90vh] w-full max-w-[420px] overflow-y-auto rounded-[26px] bg-white p-6 shadow-2xl sm:p-8"><div className="flex items-start justify-between"><div><Pill color="teal">{mode === "signup" ? "Create your account" : "Welcome back"}</Pill><h2 className="font-display mt-4 text-2xl">{mode === "signup" ? "Let’s get you set up." : "Good to see you again."}</h2></div><button aria-label="Close" onClick={onClose} className="text-[#8aa0a8]"><X size={20} /></button></div><div className="mt-6 space-y-3">{mode === "signup" && <input aria-label="Name" value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} placeholder="Full name" className="h-11 w-full rounded-xl border border-[#dce9ea] px-3 text-sm outline-none focus:border-[#0d9488]" />}<input aria-label="Email" type="email" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} placeholder="Email address" className="h-11 w-full rounded-xl border border-[#dce9ea] px-3 text-sm outline-none focus:border-[#0d9488]" /><div><input aria-label="Password" type="password" value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} onKeyDown={e => e.key === "Enter" && submit()} placeholder={mode === "signup" ? "Create a password" : "Password"} className="h-11 w-full rounded-xl border border-[#dce9ea] px-3 text-sm outline-none focus:border-[#0d9488]" />{liveIssues.length > 0 && <ul className="mt-1.5 space-y-0.5 pl-1">{liveIssues.map(issue => <li key={issue} className="text-[11px] text-[#d95d3f]">{issue}</li>)}</ul>}</div></div>{error && <p className="mt-3 text-xs font-semibold text-[#d95d3f]">{error}</p>}<Button className="mt-5 w-full justify-center" onClick={submit}>{pending ? "Please wait..." : mode === "signup" ? "Create account" : "Sign in"}</Button><p className="mt-5 text-center text-xs text-[#8aa0a8]">{mode === "signup" ? <>Already have an account? <button onClick={() => { setError(null); onSwitchMode("signin"); }} className="font-bold text-[#0f766e]">Sign in</button></> : <>New here? <button onClick={() => { setError(null); onSwitchMode("signup"); }} className="font-bold text-[#0f766e]">Create an account</button></>}</p>{isManusLoginConfigured && <div className="mt-5 border-t border-[#edf3f3] pt-5 text-center"><button onClick={() => { onClose(); startLogin(); }} className="text-xs font-bold text-[#52717d] hover:text-[#0f766e]">Or continue with Manus →</button></div>}</div></div>;
}

